#!/bin/bash
#
# Umbrella Systems — Desktop Support Shortcut Installer (App Version)
# Deploys "Submit a Ticket" app shortcut to all users' desktops on OHM MacBooks.
#
# Run as root via ScreenConnect.
# Creates a LaunchAgent so the shortcut appears for every user at login,
# including users who log in for the first time after installation.
#
# Uses a .app bundle instead of .webloc so macOS hides the extension by default.
#

set -e

INSTALL_DIR="/Library/UmbrellaSystems"
APP_NAME="Submit a Ticket.app"
ICON_NAME="umbrella-icon.png"
AGENT_LABEL="com.umbrellasystems.desktop-shortcut"
AGENT_PLIST="/Library/LaunchAgents/${AGENT_LABEL}.plist"
LOGIN_SCRIPT="${INSTALL_DIR}/setup-shortcut.sh"
TICKET_URL="https://umbrellasystems.freshdesk.com/support/tickets/new"

echo "[Umbrella] Installing support shortcut (app version)..."

mkdir -p "$INSTALL_DIR"

# --- Build the .app bundle (AppleScript applet that opens the ticket URL) ---
/usr/bin/osacompile -o "${INSTALL_DIR}/${APP_NAME}" -e "open location \"${TICKET_URL}\""

# --- Icon PNG (base64-encoded inline) ---
base64 -D -o "${INSTALL_DIR}/${ICON_NAME}" << 'ICON_EOF'

ICON_EOF

# --- Login script (copies app to each user's Desktop, sets custom icon) ---
cat > "$LOGIN_SCRIPT" << 'LOGIN_EOF'
#!/bin/bash
INSTALL_DIR="/Library/UmbrellaSystems"
APP="Submit a Ticket.app"
TARGET="$HOME/Desktop/$APP"

if [ ! -d "$TARGET" ]; then
    cp -R "${INSTALL_DIR}/${APP}" "$TARGET"
fi

# Set custom icon using JXA (ObjC bridge — no dependencies, ships with macOS)
/usr/bin/osascript -l JavaScript << 'JXA' 2>/dev/null || true
ObjC.import('Cocoa');
try {
    var home = $.NSProcessInfo.processInfo.environment.objectForKey('HOME').js;
    var iconPath = '/Library/UmbrellaSystems/umbrella-icon.png';
    var targetPath = home + '/Desktop/Submit a Ticket.app';
    var image = $.NSImage.alloc.initWithContentsOfFile(iconPath);
    $.NSWorkspace.sharedWorkspace.setIconForFileOptions(image, targetPath, 0);
} catch(e) {}
JXA
LOGIN_EOF

chmod +x "$LOGIN_SCRIPT"

# --- LaunchAgent (triggers login script for every user) ---
cat > "$AGENT_PLIST" << PLIST_EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
	<key>Label</key>
	<string>${AGENT_LABEL}</string>
	<key>ProgramArguments</key>
	<array>
		<string>/bin/bash</string>
		<string>${LOGIN_SCRIPT}</string>
	</array>
	<key>RunAtLoad</key>
	<true/>
</dict>
</plist>
PLIST_EOF

chmod 644 "$AGENT_PLIST"
chmod 644 "${INSTALL_DIR}/${ICON_NAME}"

# --- Run immediately for the currently logged-in user ---
CURRENT_USER=$(stat -f "%Su" /dev/console 2>/dev/null)
if [ -n "$CURRENT_USER" ] && [ "$CURRENT_USER" != "root" ] && [ "$CURRENT_USER" != "loginwindow" ]; then
    CURRENT_UID=$(id -u "$CURRENT_USER" 2>/dev/null)
    if [ -n "$CURRENT_UID" ]; then
        launchctl bootout "gui/${CURRENT_UID}/${AGENT_LABEL}" 2>/dev/null || true
        launchctl bootstrap "gui/${CURRENT_UID}" "$AGENT_PLIST" 2>/dev/null || \
            sudo -u "$CURRENT_USER" launchctl load "$AGENT_PLIST" 2>/dev/null || true
    fi
fi

echo "[Umbrella] Done. Shortcut will appear on all users' desktops at next login."
